-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Phase 2: Curriculum Sessions, session-scoped teachers, hashed QR check-in,
-- attendance-based completion and completion-gated study notes.
-- Forward-only. Tables are renamed in place so IDs, rows and FKs are preserved.
BEGIN;

-- ---------------------------------------------------------------------------
-- 1. events -> curriculum_sessions (one canonical session model)
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS "events: active users read open events" ON lms.events;
DROP POLICY IF EXISTS "events: scoped admin manage" ON lms.events;
DROP POLICY IF EXISTS "events: admin all" ON lms.events;
DROP POLICY IF EXISTS "event_attendances: learner read own" ON lms.event_attendances;
DROP POLICY IF EXISTS "event_attendances: learner enroll self" ON lms.event_attendances;
DROP POLICY IF EXISTS "event_attendances: manager read/manage" ON lms.event_attendances;
DROP POLICY IF EXISTS "event_attendances: admin all" ON lms.event_attendances;
DROP TRIGGER IF EXISTS validate_event_teacher ON lms.events;
-- Its body references lms.events; replaced by is_session_manager().
DROP FUNCTION IF EXISTS lms.is_event_manager(uuid);

ALTER TABLE lms.events RENAME TO curriculum_sessions;
ALTER TABLE lms.curriculum_sessions RENAME COLUMN name TO title;
ALTER TABLE lms.curriculum_sessions RENAME COLUMN start_date TO starts_at;
ALTER TABLE lms.curriculum_sessions RENAME COLUMN end_date TO ends_at;
-- Deprecated single-teacher column, retained read-only for rollback evidence.
ALTER TABLE lms.curriculum_sessions RENAME COLUMN teacher_id TO legacy_teacher_id;
ALTER TABLE lms.curriculum_sessions RENAME CONSTRAINT events_pkey TO curriculum_sessions_pkey;
ALTER TABLE lms.curriculum_sessions RENAME CONSTRAINT events_module_id_fkey TO curriculum_sessions_module_id_fkey;
ALTER TABLE lms.curriculum_sessions RENAME CONSTRAINT events_created_by_fkey TO curriculum_sessions_created_by_fkey;
ALTER TABLE lms.curriculum_sessions RENAME CONSTRAINT events_teacher_id_fkey TO curriculum_sessions_legacy_teacher_id_fkey;
ALTER INDEX lms.idx_events_teacher_id RENAME TO idx_curriculum_sessions_legacy_teacher_id;
ALTER INDEX lms.idx_events_created_by RENAME TO idx_curriculum_sessions_created_by;

ALTER TABLE lms.curriculum_sessions
  ADD COLUMN status text NOT NULL DEFAULT 'scheduled',
  ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();

-- Legacy events had optional times. Sessions need an explicit window: missing
-- starts use creation time; missing or non-positive windows get two hours.
UPDATE lms.curriculum_sessions SET starts_at = created_at WHERE starts_at IS NULL;
UPDATE lms.curriculum_sessions SET ends_at = starts_at + interval '2 hours'
WHERE ends_at IS NULL OR ends_at <= starts_at;
UPDATE lms.curriculum_sessions SET status = 'completed' WHERE ends_at < now();
UPDATE lms.curriculum_sessions SET title = 'Untitled session' WHERE btrim(title) = '';

ALTER TABLE lms.curriculum_sessions
  ALTER COLUMN starts_at SET NOT NULL,
  ALTER COLUMN ends_at SET NOT NULL,
  ADD CONSTRAINT curriculum_sessions_status_check
    CHECK (status IN ('scheduled', 'active', 'completed', 'cancelled')),
  ADD CONSTRAINT curriculum_sessions_window_check CHECK (ends_at > starts_at),
  ADD CONSTRAINT curriculum_sessions_title_check CHECK (btrim(title) <> ''),
  -- Target for the composite provenance FK on learner_progress.
  ADD CONSTRAINT curriculum_sessions_id_module_key UNIQUE (id, module_id);

CREATE INDEX idx_curriculum_sessions_module ON lms.curriculum_sessions(module_id);
CREATE INDEX idx_curriculum_sessions_starts_at ON lms.curriculum_sessions(starts_at);
CREATE INDEX idx_curriculum_sessions_status ON lms.curriculum_sessions(status);

CREATE TRIGGER update_curriculum_sessions_updated_at BEFORE UPDATE ON lms.curriculum_sessions
  FOR EACH ROW EXECUTE FUNCTION lms.update_updated_at_column();

-- A session's module anchors teaching grants and completion provenance.
CREATE FUNCTION lms.prevent_session_module_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW.module_id IS DISTINCT FROM OLD.module_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A session''s module cannot be changed';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.prevent_session_module_change() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER prevent_session_module_change BEFORE UPDATE OF module_id ON lms.curriculum_sessions
  FOR EACH ROW EXECUTE FUNCTION lms.prevent_session_module_change();

-- ---------------------------------------------------------------------------
-- 2. session_teachers (many Admin teachers per session)
-- ---------------------------------------------------------------------------
CREATE TABLE lms.session_teachers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES lms.curriculum_sessions(id) ON DELETE CASCADE,
  -- No cascade: teaching history must survive; accounts are soft-deleted.
  admin_id uuid NOT NULL REFERENCES lms.users(id),
  assigned_by uuid REFERENCES lms.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT session_teachers_session_admin_key UNIQUE (session_id, admin_id)
);
CREATE INDEX idx_session_teachers_admin ON lms.session_teachers(admin_id);
CREATE INDEX idx_session_teachers_assigned_by ON lms.session_teachers(assigned_by);

-- Preserve historical hosts before validation exists (legacy code treated
-- teacher_id, falling back to created_by, as the host).
INSERT INTO lms.session_teachers (session_id, admin_id, assigned_by, created_at)
SELECT id, coalesce(legacy_teacher_id, created_by), created_by, created_at
FROM lms.curriculum_sessions;

-- New/changed assignments: active Admin with a grant for the session module,
-- or an active Super Admin. Row locks serialize with demotion and revocation.
CREATE FUNCTION lms.validate_session_teacher() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  teacher_role text;
  session_module uuid;
BEGIN
  SELECT role INTO teacher_role FROM lms.users
  WHERE id = NEW.admin_id AND role IN ('admin', 'super_admin') AND is_active AND deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Session teachers must be active Admins';
  END IF;
  SELECT module_id INTO session_module FROM lms.curriculum_sessions WHERE id = NEW.session_id;
  IF teacher_role <> 'super_admin' THEN
    PERFORM 1 FROM lms.module_teaching_permissions
    WHERE user_id = NEW.admin_id AND module_id = session_module FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'Selected Admin does not have teaching permission for this module';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION lms.validate_session_teacher() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER validate_session_teacher BEFORE INSERT OR UPDATE ON lms.session_teachers
  FOR EACH ROW EXECUTE FUNCTION lms.validate_session_teacher();

-- ---------------------------------------------------------------------------
-- 3. session_qr_tokens (only SHA-256 hashes are stored)
-- ---------------------------------------------------------------------------
CREATE TABLE lms.session_qr_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES lms.curriculum_sessions(id) ON DELETE CASCADE,
  token_hash bytea NOT NULL CONSTRAINT session_qr_tokens_token_hash_key UNIQUE
    CHECK (octet_length(token_hash) = 32),
  valid_from timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  created_by uuid NOT NULL REFERENCES lms.users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT session_qr_tokens_window_check CHECK (expires_at > valid_from)
);
CREATE INDEX idx_session_qr_tokens_session ON lms.session_qr_tokens(session_id);
CREATE INDEX idx_session_qr_tokens_created_by ON lms.session_qr_tokens(created_by);

-- ---------------------------------------------------------------------------
-- 4. event_attendances -> session_attendances
-- ---------------------------------------------------------------------------
ALTER TABLE lms.event_attendances RENAME TO session_attendances;
ALTER TABLE lms.session_attendances RENAME COLUMN event_id TO session_id;
ALTER TABLE lms.session_attendances RENAME COLUMN joined_at TO scanned_at;
ALTER TABLE lms.session_attendances RENAME CONSTRAINT event_attendances_pkey TO session_attendances_pkey;
ALTER TABLE lms.session_attendances RENAME CONSTRAINT event_attendances_event_id_learner_id_key TO session_attendances_session_id_learner_id_key;
ALTER TABLE lms.session_attendances RENAME CONSTRAINT event_attendances_event_id_fkey TO session_attendances_session_id_fkey;
ALTER TABLE lms.session_attendances RENAME CONSTRAINT event_attendances_learner_id_fkey TO session_attendances_learner_id_fkey;
-- Redundant with the (session_id, learner_id) unique index.
DROP INDEX IF EXISTS lms.idx_event_attendances_event_learner;
ALTER INDEX lms.idx_event_attendances_learner RENAME TO idx_session_attendances_learner;

ALTER TABLE lms.session_attendances
  ADD COLUMN attendance_method text,
  ADD COLUMN completion_granted_at timestamptz,
  ADD COLUMN recorded_by uuid REFERENCES lms.users(id) ON DELETE SET NULL,
  ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
-- Legacy enrolment cannot be distinguished between link and manual adds.
UPDATE lms.session_attendances SET attendance_method = 'legacy', created_at = scanned_at;
ALTER TABLE lms.session_attendances
  ALTER COLUMN attendance_method SET NOT NULL,
  ADD CONSTRAINT session_attendances_method_check
    CHECK (attendance_method IN ('qr', 'manual', 'import', 'override', 'legacy'));
CREATE INDEX idx_session_attendances_recorded_by ON lms.session_attendances(recorded_by);

-- ---------------------------------------------------------------------------
-- 5. learner_progress completion provenance
-- ---------------------------------------------------------------------------
ALTER TABLE lms.learner_progress
  ADD COLUMN source_session_id uuid,
  ADD COLUMN completion_method text;
UPDATE lms.learner_progress SET completion_method = 'migration' WHERE status = 'completed';
ALTER TABLE lms.learner_progress
  ADD CONSTRAINT learner_progress_completion_method_check
    CHECK (completion_method IN ('qr_attendance', 'manual_admin', 'migration', 'override')),
  -- Completion and its provenance travel together; attendance stays separate.
  ADD CONSTRAINT learner_progress_completion_provenance_check CHECK (
    (status = 'completed' AND completion_method IS NOT NULL)
    OR (status <> 'completed' AND completion_method IS NULL AND source_session_id IS NULL)),
  ADD CONSTRAINT learner_progress_qr_source_check
    CHECK (completion_method IS DISTINCT FROM 'qr_attendance' OR source_session_id IS NOT NULL),
  -- The source session must be for the same module.
  ADD CONSTRAINT learner_progress_source_session_fkey FOREIGN KEY (source_session_id, module_id)
    REFERENCES lms.curriculum_sessions(id, module_id);
CREATE INDEX idx_learner_progress_source_session ON lms.learner_progress(source_session_id);

-- ---------------------------------------------------------------------------
-- 6. Authorization helpers
-- ---------------------------------------------------------------------------
CREATE FUNCTION lms_private.session_checkin_grace() RETURNS interval
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT interval '30 minutes' $$;
REVOKE ALL ON FUNCTION lms_private.session_checkin_grace() FROM PUBLIC, anon, authenticated, service_role;

CREATE FUNCTION lms.is_session_teacher(target_session_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_admin() AND EXISTS (SELECT 1 FROM lms.session_teachers
    WHERE session_id = target_session_id AND admin_id = auth.uid());
$$;

-- Managing requires manage_sessions AND a teaching grant for the module AND
-- ownership/teaching of the session (Phase 1 separation preserved).
CREATE FUNCTION lms.is_session_manager(target_session_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_super_admin() OR (lms.has_admin_permission('manage_sessions') AND EXISTS (
    SELECT 1 FROM lms.curriculum_sessions s
    WHERE s.id = target_session_id AND s.deleted_at IS NULL
      AND lms.can_teach_module(s.module_id)
      AND (s.created_by = auth.uid() OR EXISTS (SELECT 1 FROM lms.session_teachers st
        WHERE st.session_id = s.id AND st.admin_id = auth.uid()))));
$$;

CREATE FUNCTION lms.can_view_session(target_session_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_session_manager(target_session_id)
    OR lms.is_session_teacher(target_session_id)
    OR lms.has_admin_permission('view_session_tracking')
    OR (lms.is_active_app_user(auth.uid()) AND EXISTS (SELECT 1 FROM lms.session_attendances
      WHERE session_id = target_session_id AND learner_id = auth.uid()));
$$;

-- Session-scoped replacement for permanent teacher assignment: the caller
-- created or taught a (non-deleted) session of this module that the learner
-- attended, and still holds the module teaching grant.
CREATE FUNCTION lms.is_session_teacher_for_learner(target_learner_id uuid, target_module_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.can_teach_module(target_module_id) AND EXISTS (
    SELECT 1 FROM lms.session_attendances a
    JOIN lms.curriculum_sessions s ON s.id = a.session_id
    WHERE a.learner_id = target_learner_id AND s.module_id = target_module_id AND s.deleted_at IS NULL
      AND (s.created_by = auth.uid() OR EXISTS (SELECT 1 FROM lms.session_teachers st
        WHERE st.session_id = s.id AND st.admin_id = auth.uid())));
$$;

-- Study notes: completed learners, module teachers, curriculum managers.
CREATE FUNCTION lms.can_access_module_notes(target_module_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT lms.is_active_app_user(auth.uid()) AND EXISTS (
    SELECT 1 FROM lms.modules m
    WHERE m.id = target_module_id AND m.deleted_at IS NULL AND (
      lms.has_admin_permission('manage_curriculum')
      OR (m.is_published AND (lms.can_teach_module(m.id) OR EXISTS (
        SELECT 1 FROM lms.learner_progress p
        WHERE p.learner_id = auth.uid() AND p.module_id = m.id AND p.status = 'completed')))));
$$;

REVOKE ALL ON FUNCTION lms.is_session_teacher(uuid), lms.is_session_manager(uuid),
  lms.can_view_session(uuid), lms.is_session_teacher_for_learner(uuid, uuid),
  lms.can_access_module_notes(uuid) FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION lms.is_session_teacher(uuid), lms.is_session_manager(uuid),
  lms.can_view_session(uuid), lms.is_session_teacher_for_learner(uuid, uuid),
  lms.can_access_module_notes(uuid) TO authenticated;

-- Locks the caller's account and session grants, then re-checks them, so a
-- concurrent demotion/revocation cannot interleave with a session write.
CREATE FUNCTION lms_private.require_session_authority(target_module_id uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
BEGIN
  PERFORM 1 FROM lms.users WHERE id = actor FOR SHARE;
  PERFORM 1 FROM lms.admin_permissions WHERE user_id = actor AND permission = 'manage_sessions' FOR SHARE;
  PERFORM 1 FROM lms.module_teaching_permissions WHERE user_id = actor AND module_id = target_module_id FOR SHARE;
  IF NOT lms.is_active_app_user(actor) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Account is inactive';
  END IF;
  IF NOT lms.has_admin_permission('manage_sessions') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Permission required: manage_sessions';
  END IF;
  IF NOT lms.can_teach_module(target_module_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Module teaching permission required';
  END IF;
  RETURN actor;
END;
$$;

-- Loads and locks a session the caller manages.
CREATE FUNCTION lms_private.lock_managed_session(target_session_id uuid)
RETURNS lms.curriculum_sessions
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
BEGIN
  SELECT * INTO target FROM lms.curriculum_sessions WHERE id = target_session_id FOR UPDATE;
  IF NOT FOUND OR target.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Session not found';
  END IF;
  PERFORM lms_private.require_session_authority(target.module_id);
  IF NOT lms.is_session_manager(target_session_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Session access denied';
  END IF;
  RETURN target;
END;
$$;

CREATE FUNCTION lms_private.validate_session_details(session_title text, session_start timestamptz, session_end timestamptz)
RETURNS void
LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
BEGIN
  IF session_title IS NULL OR char_length(btrim(session_title)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Session title must be 1-200 characters';
  END IF;
  IF session_start IS NULL OR session_end IS NULL OR session_end <= session_start THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Session end time must be after its start time';
  END IF;
  IF session_end - session_start > interval '7 days' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Sessions cannot be longer than 7 days';
  END IF;
END;
$$;

CREATE FUNCTION lms_private.replace_session_teachers(target_session_id uuid, target_module_id uuid,
  teacher_ids uuid[], actor uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  requested integer := coalesce(cardinality(teacher_ids), 0);
BEGIN
  IF requested = 0 OR requested > 20 OR array_position(teacher_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Assign between 1 and 20 teachers';
  END IF;
  IF (SELECT count(DISTINCT t) FROM unnest(teacher_ids) t) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Duplicate teacher selected';
  END IF;
  IF (SELECT count(*) FROM lms.users u WHERE u.id = ANY (teacher_ids)
      AND u.is_active AND u.deleted_at IS NULL
      AND (u.role = 'super_admin' OR (u.role = 'admin' AND EXISTS (
        SELECT 1 FROM lms.module_teaching_permissions g
        WHERE g.user_id = u.id AND g.module_id = target_module_id)))) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'One or more selected teachers cannot teach this module';
  END IF;
  -- Removing a teacher only affects the session roster; history elsewhere
  -- (learner_progress.source_session_id) keeps pointing at the session.
  DELETE FROM lms.session_teachers WHERE session_id = target_session_id AND admin_id <> ALL (teacher_ids);
  INSERT INTO lms.session_teachers (session_id, admin_id, assigned_by)
  SELECT target_session_id, t, actor FROM unnest(teacher_ids) t
  ON CONFLICT (session_id, admin_id) DO NOTHING;
END;
$$;

REVOKE ALL ON FUNCTION lms_private.require_session_authority(uuid), lms_private.lock_managed_session(uuid),
  lms_private.validate_session_details(text, timestamptz, timestamptz),
  lms_private.replace_session_teachers(uuid, uuid, uuid[], uuid) FROM PUBLIC, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 7. Session management RPCs (authorization + write + audit in one transaction)
-- ---------------------------------------------------------------------------
CREATE FUNCTION lms.list_session_teacher_candidates(target_module_id uuid)
RETURNS TABLE (candidate_id uuid, candidate_name text, candidate_is_super_admin boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT (lms.has_admin_permission('manage_sessions') AND lms.can_teach_module(target_module_id)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Session management permission required';
  END IF;
  RETURN QUERY
  SELECT u.id, u.full_name, u.role = 'super_admin' FROM lms.users u
  WHERE u.is_active AND u.deleted_at IS NULL
    AND (u.role = 'super_admin' OR (u.role = 'admin' AND EXISTS (
      SELECT 1 FROM lms.module_teaching_permissions g
      WHERE g.user_id = u.id AND g.module_id = target_module_id)))
  ORDER BY u.full_name NULLS LAST, u.id;
END;
$$;

CREATE FUNCTION lms.create_curriculum_session(target_module_id uuid, session_title text,
  session_starts_at timestamptz, session_ends_at timestamptz, teacher_ids uuid[]) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid;
  new_session_id uuid;
BEGIN
  actor := lms_private.require_session_authority(target_module_id);
  PERFORM 1 FROM lms.modules WHERE id = target_module_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Module not found';
  END IF;
  PERFORM lms_private.validate_session_details(session_title, session_starts_at, session_ends_at);

  INSERT INTO lms.curriculum_sessions (module_id, title, starts_at, ends_at, status, created_by)
  VALUES (target_module_id, btrim(session_title), session_starts_at, session_ends_at, 'scheduled', actor)
  RETURNING id INTO new_session_id;
  PERFORM lms_private.replace_session_teachers(new_session_id, target_module_id, teacher_ids, actor);

  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (actor, 'session_created', 'curriculum_sessions', new_session_id, jsonb_build_object(
    'session_id', new_session_id, 'module_id', target_module_id, 'teacher_ids', to_jsonb(teacher_ids),
    'starts_at', session_starts_at, 'ends_at', session_ends_at));
  RETURN new_session_id;
END;
$$;

CREATE FUNCTION lms.update_curriculum_session(target_session_id uuid, session_title text,
  session_starts_at timestamptz, session_ends_at timestamptz, teacher_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  previous_teachers uuid[];
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status = 'cancelled' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cancelled sessions cannot be edited';
  END IF;
  PERFORM lms_private.validate_session_details(session_title, session_starts_at, session_ends_at);
  SELECT coalesce(array_agg(admin_id ORDER BY admin_id), '{}') INTO previous_teachers
  FROM lms.session_teachers WHERE session_id = target.id;

  UPDATE lms.curriculum_sessions
  SET title = btrim(session_title), starts_at = session_starts_at, ends_at = session_ends_at
  WHERE id = target.id;
  PERFORM lms_private.replace_session_teachers(target.id, target.module_id, teacher_ids, auth.uid());

  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'session_updated', 'curriculum_sessions', target.id, jsonb_build_object(
    'session_id', target.id, 'module_id', target.module_id,
    'previous', jsonb_build_object('title', target.title, 'starts_at', target.starts_at,
      'ends_at', target.ends_at, 'teacher_ids', to_jsonb(previous_teachers)),
    'current', jsonb_build_object('title', btrim(session_title), 'starts_at', session_starts_at,
      'ends_at', session_ends_at, 'teacher_ids', to_jsonb(teacher_ids))));
END;
$$;

-- Ends check-in: 'completed' (closed normally) or 'cancelled'. Revokes QR.
CREATE FUNCTION lms.close_curriculum_session(target_session_id uuid, final_status text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  revoked_count integer;
BEGIN
  IF final_status NOT IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Invalid session status';
  END IF;
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Session is already closed';
  END IF;
  UPDATE lms.curriculum_sessions SET status = final_status WHERE id = target.id;
  UPDATE lms.session_qr_tokens SET revoked_at = now()
  WHERE session_id = target.id AND revoked_at IS NULL;
  GET DIAGNOSTICS revoked_count = ROW_COUNT;

  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (auth.uid(),
    CASE final_status WHEN 'cancelled' THEN 'session_cancelled'::lms.activity_event
      ELSE 'session_completed'::lms.activity_event END,
    'curriculum_sessions', target.id, jsonb_build_object('session_id', target.id,
      'module_id', target.module_id, 'previous_status', target.status, 'revoked_qr_tokens', revoked_count));
END;
$$;

-- Issues a fresh QR token and revokes older ones (one live QR per session).
-- The raw token is returned once and never stored.
CREATE FUNCTION lms.issue_session_qr_token(target_session_id uuid)
RETURNS TABLE (token text, token_id uuid, token_valid_from timestamptz, token_expires_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  grace interval := lms_private.session_checkin_grace();
  raw_token text;
  new_token_id uuid;
  replaced integer;
  opens timestamptz;
  closes timestamptz;
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status NOT IN ('scheduled', 'active') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Session is closed';
  END IF;
  closes := target.ends_at + grace;
  opens := target.starts_at - grace;
  IF now() >= closes THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Session check-in window has ended';
  END IF;

  UPDATE lms.session_qr_tokens SET revoked_at = now()
  WHERE session_id = target.id AND revoked_at IS NULL;
  GET DIAGNOSTICS replaced = ROW_COUNT;

  -- 256 random bits, base64url without padding (43 characters).
  raw_token := rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');
  INSERT INTO lms.session_qr_tokens (session_id, token_hash, valid_from, expires_at, created_by)
  VALUES (target.id, sha256(convert_to(raw_token, 'UTF8')), opens, closes, auth.uid())
  RETURNING id INTO new_token_id;
  UPDATE lms.curriculum_sessions SET status = 'active' WHERE id = target.id AND status = 'scheduled';

  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'session_qr_generated', 'curriculum_sessions', target.id, jsonb_build_object(
    'session_id', target.id, 'module_id', target.module_id, 'token_id', new_token_id,
    'replaced_tokens', replaced, 'valid_from', opens, 'expires_at', closes));
  RETURN QUERY SELECT raw_token, new_token_id, opens, closes;
END;
$$;

CREATE FUNCTION lms.revoke_session_qr_tokens(target_session_id uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  revoked_count integer;
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  UPDATE lms.session_qr_tokens SET revoked_at = now()
  WHERE session_id = target.id AND revoked_at IS NULL;
  GET DIAGNOSTICS revoked_count = ROW_COUNT;
  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'session_qr_revoked', 'curriculum_sessions', target.id, jsonb_build_object(
    'session_id', target.id, 'module_id', target.module_id, 'revoked_tokens', revoked_count));
  RETURN revoked_count;
END;
$$;

-- Manual attendance. Records attendance only; completion stays a separate,
-- explicitly authorized manual action. Never touches cohort/teacher fields.
CREATE FUNCTION lms.add_session_attendees(target_session_id uuid, learner_ids uuid[]) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  requested integer := coalesce(cardinality(learner_ids), 0);
  added integer;
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status = 'cancelled' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cannot add attendees to a cancelled session';
  END IF;
  IF requested = 0 OR requested > 500 OR array_position(learner_ids, NULL) IS NOT NULL
     OR (SELECT count(DISTINCT l) FROM unnest(learner_ids) l) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Invalid learner selection';
  END IF;
  IF (SELECT count(*) FROM lms.users WHERE id = ANY (learner_ids)
      AND role = 'user' AND is_active AND deleted_at IS NULL) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'One or more learners are not eligible';
  END IF;

  WITH inserted AS (
    INSERT INTO lms.session_attendances (session_id, learner_id, attendance_method, recorded_by)
    SELECT target.id, l, 'manual', auth.uid() FROM unnest(learner_ids) l
    ON CONFLICT (session_id, learner_id) DO NOTHING
    RETURNING id, learner_id
  ), progress AS (
    INSERT INTO lms.learner_progress (learner_id, module_id, status, started_at)
    SELECT learner_id, target.module_id, 'in_progress', now() FROM inserted
    ON CONFLICT (learner_id, module_id) DO NOTHING
  ), logged AS (
    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    SELECT learner_id, 'session_attendance_recorded', 'session_attendances', id, jsonb_build_object(
      'session_id', target.id, 'module_id', target.module_id, 'attendance_method', 'manual',
      'recorded_by', auth.uid(), 'completion_granted', false)
    FROM inserted
  )
  SELECT count(*) INTO added FROM inserted;
  RETURN added;
END;
$$;

-- Manual completion/un-completion with atomic audit. Authorization mirrors the
-- Phase 1 rule (module grant + learner relationship) and adds the
-- session-scoped relationship; Super Admins may act on anyone.
CREATE FUNCTION lms.set_module_completion(target_learner_id uuid, target_module_id uuid, completed boolean)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
  existing lms.learner_progress;
  stamp timestamptz := now();
BEGIN
  PERFORM 1 FROM lms.users WHERE id = actor FOR SHARE;
  PERFORM 1 FROM lms.module_teaching_permissions
  WHERE user_id = actor AND module_id = target_module_id FOR SHARE;
  IF NOT lms.is_active_app_user(actor) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Account is inactive';
  END IF;
  IF NOT (lms.is_super_admin() OR (lms.can_teach_module(target_module_id) AND (
      lms.is_assigned_teacher(target_learner_id)
      OR EXISTS (SELECT 1 FROM lms.learner_progress WHERE learner_id = target_learner_id
        AND module_id = target_module_id AND teacher_id = actor)
      OR lms.is_session_teacher_for_learner(target_learner_id, target_module_id)))) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Learner access denied';
  END IF;
  PERFORM 1 FROM lms.modules WHERE id = target_module_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Module not found';
  END IF;

  SELECT * INTO existing FROM lms.learner_progress
  WHERE learner_id = target_learner_id AND module_id = target_module_id FOR UPDATE;

  IF completed THEN
    IF existing.status = 'completed' THEN
      RETURN jsonb_build_object('changed', false, 'status', 'completed');
    END IF;
    INSERT INTO lms.learner_progress AS lp (learner_id, module_id, status, started_at, completed_at,
      marked_by, completion_method)
    VALUES (target_learner_id, target_module_id, 'completed', stamp, stamp, actor, 'manual_admin')
    ON CONFLICT (learner_id, module_id) DO UPDATE SET status = 'completed',
      started_at = coalesce(lp.started_at, EXCLUDED.started_at),
      completed_at = EXCLUDED.completed_at, marked_by = EXCLUDED.marked_by,
      completion_method = 'manual_admin', source_session_id = NULL;
    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    VALUES (target_learner_id, 'module_completed', 'modules', target_module_id, jsonb_build_object(
      'module_id', target_module_id, 'marked_by', actor, 'learner_initiated', false,
      'completion_method', 'manual_admin'));
    RETURN jsonb_build_object('changed', true, 'status', 'completed');
  END IF;

  IF existing.id IS NULL OR existing.status <> 'completed' THEN
    RETURN jsonb_build_object('changed', false, 'status', coalesce(existing.status, 'not_started'));
  END IF;
  UPDATE lms.learner_progress
  SET status = CASE WHEN started_at IS NOT NULL THEN 'in_progress' ELSE 'not_started' END,
    completed_at = NULL, marked_by = NULL, completion_method = NULL, source_session_id = NULL
  WHERE id = existing.id;
  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (target_learner_id, 'module_updated', 'modules', target_module_id, jsonb_build_object(
    'module_id', target_module_id, 'action', 'unmarked_complete', 'unmarked_by', actor,
    'previous_completion_method', existing.completion_method,
    'previous_source_session_id', existing.source_session_id,
    'previous_completed_at', existing.completed_at));
  RETURN jsonb_build_object('changed', true, 'status',
    CASE WHEN existing.started_at IS NOT NULL THEN 'in_progress' ELSE 'not_started' END);
END;
$$;

-- ---------------------------------------------------------------------------
-- 8. QR scan: validate -> attendance -> completion -> audit, atomically.
-- Identity comes only from auth.uid(). Expected failures return a result code
-- (nothing has been written); unexpected errors roll the whole call back.
-- ---------------------------------------------------------------------------
CREATE FUNCTION lms.scan_session_qr(qr_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  learner uuid := auth.uid();
  scanned timestamptz := now();
  grace interval := lms_private.session_checkin_grace();
  account record;
  qr record;
  target record;
  target_module record;
  attendance_id uuid;
  attendance_scanned_at timestamptz;
  attendance_method text;
  newly_completed_at timestamptz;
  already_attended boolean := false;
  progress record;
BEGIN
  IF learner IS NULL THEN
    RETURN jsonb_build_object('result', 'unauthenticated');
  END IF;
  -- Shares the row lock with deactivation/demotion, which must wait for us.
  SELECT role, is_active, deleted_at INTO account FROM lms.users WHERE id = learner FOR SHARE;
  IF NOT FOUND OR NOT account.is_active OR account.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'inactive_account');
  END IF;
  IF account.role NOT IN ('user', 'admin') THEN
    RETURN jsonb_build_object('result', 'role_not_allowed');
  END IF;
  IF qr_token IS NULL OR qr_token !~ '^[A-Za-z0-9_-]{43}$' THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;

  SELECT session_id INTO qr FROM lms.session_qr_tokens
  WHERE token_hash = sha256(convert_to(qr_token, 'UTF8'));
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;
  -- Lock order session -> token matches the management RPCs (no deadlock).
  -- FOR SHARE makes an in-flight cancel/revoke finish first; it is then observed.
  SELECT id, module_id, title, starts_at, ends_at, status, deleted_at INTO target
  FROM lms.curriculum_sessions WHERE id = qr.session_id FOR SHARE;
  SELECT id, session_id, valid_from, expires_at, revoked_at INTO qr
  FROM lms.session_qr_tokens WHERE token_hash = sha256(convert_to(qr_token, 'UTF8')) FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;
  IF qr.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'revoked_token');
  END IF;
  IF scanned > qr.expires_at THEN
    RETURN jsonb_build_object('result', 'expired_token');
  END IF;
  IF scanned < qr.valid_from THEN
    RETURN jsonb_build_object('result', 'session_not_open');
  END IF;
  IF target.id IS NULL OR target.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'session_unavailable');
  END IF;
  IF target.status = 'cancelled' THEN
    RETURN jsonb_build_object('result', 'session_cancelled');
  END IF;
  IF target.status = 'completed' OR scanned > target.ends_at + grace THEN
    RETURN jsonb_build_object('result', 'session_closed');
  END IF;
  IF scanned < target.starts_at - grace THEN
    RETURN jsonb_build_object('result', 'session_not_open');
  END IF;

  SELECT id, title, module_code, is_published, deleted_at INTO target_module
  FROM lms.modules WHERE id = target.module_id;
  IF NOT FOUND OR target_module.deleted_at IS NOT NULL OR NOT target_module.is_published THEN
    RETURN jsonb_build_object('result', 'module_unavailable');
  END IF;
  IF EXISTS (SELECT 1 FROM lms.session_teachers WHERE session_id = target.id AND admin_id = learner) THEN
    RETURN jsonb_build_object('result', 'teacher_cannot_attend');
  END IF;

  INSERT INTO lms.session_attendances (session_id, learner_id, scanned_at, attendance_method, created_at)
  VALUES (target.id, learner, scanned, 'qr', scanned)
  ON CONFLICT (session_id, learner_id) DO NOTHING
  RETURNING id, scanned_at, session_attendances.attendance_method
  INTO attendance_id, attendance_scanned_at, attendance_method;

  IF attendance_id IS NULL THEN
    -- Duplicate scan: strictly idempotent, no writes.
    already_attended := true;
    SELECT a.id, a.scanned_at, a.attendance_method INTO attendance_id, attendance_scanned_at, attendance_method
    FROM lms.session_attendances a WHERE a.session_id = target.id AND a.learner_id = learner;
  ELSE
    -- Only a first completion sets provenance; an existing completion keeps it.
    INSERT INTO lms.learner_progress AS lp (learner_id, module_id, status, started_at, completed_at,
      source_session_id, completion_method)
    VALUES (learner, target.module_id, 'completed', scanned, scanned, target.id, 'qr_attendance')
    ON CONFLICT (learner_id, module_id) DO UPDATE SET status = 'completed',
      started_at = coalesce(lp.started_at, EXCLUDED.started_at),
      completed_at = EXCLUDED.completed_at, source_session_id = EXCLUDED.source_session_id,
      completion_method = EXCLUDED.completion_method, marked_by = NULL
    WHERE lp.status <> 'completed'
    RETURNING lp.completed_at INTO newly_completed_at;

    IF newly_completed_at IS NOT NULL THEN
      UPDATE lms.session_attendances SET completion_granted_at = newly_completed_at
      WHERE id = attendance_id;
    END IF;

    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    VALUES (learner, 'session_attendance_recorded', 'session_attendances', attendance_id, jsonb_build_object(
      'session_id', target.id, 'module_id', target.module_id, 'attendance_method', 'qr',
      'qr_token_id', qr.id, 'completion_granted', newly_completed_at IS NOT NULL));
    IF newly_completed_at IS NOT NULL THEN
      INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
      VALUES (learner, 'module_completed', 'modules', target.module_id, jsonb_build_object(
        'module_id', target.module_id, 'session_id', target.id, 'attendance_id', attendance_id,
        'completion_method', 'qr_attendance', 'learner_initiated', true));
    END IF;
  END IF;

  SELECT status, completed_at, completion_method, source_session_id INTO progress
  FROM lms.learner_progress WHERE learner_id = learner AND module_id = target.module_id;

  RETURN jsonb_build_object(
    'result', CASE WHEN already_attended THEN 'already_attended'
      WHEN newly_completed_at IS NOT NULL THEN 'completed' ELSE 'attended_previously_completed' END,
    'session', jsonb_build_object('id', target.id, 'title', target.title,
      'starts_at', target.starts_at, 'ends_at', target.ends_at),
    'module', jsonb_build_object('id', target_module.id, 'title', target_module.title,
      'module_code', target_module.module_code),
    'teachers', (SELECT coalesce(jsonb_agg(coalesce(u.full_name, 'Admin') ORDER BY u.full_name), '[]'::jsonb)
      FROM lms.session_teachers st JOIN lms.users u ON u.id = st.admin_id WHERE st.session_id = target.id),
    'attendance', jsonb_build_object('id', attendance_id, 'scanned_at', attendance_scanned_at,
      'method', attendance_method),
    'progress', jsonb_build_object('status', progress.status, 'completed_at', progress.completed_at,
      'completion_method', progress.completion_method,
      'source_session_id', progress.source_session_id),
    'notes_unlocked', progress.status = 'completed');
END;
$$;

-- Learner-facing provenance: which session and teachers completed my module.
CREATE FUNCTION lms.get_my_module_completion(target_module_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT CASE WHEN NOT lms.is_active_app_user(auth.uid()) THEN NULL ELSE (
    SELECT jsonb_build_object('status', p.status, 'completed_at', p.completed_at,
      'completion_method', p.completion_method,
      'session', CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object(
        'id', s.id, 'title', s.title, 'starts_at', s.starts_at) END,
      'teachers', (SELECT coalesce(jsonb_agg(coalesce(u.full_name, 'Admin') ORDER BY u.full_name), '[]'::jsonb)
        FROM lms.session_teachers st JOIN lms.users u ON u.id = st.admin_id
        WHERE st.session_id = s.id))
    FROM lms.learner_progress p
    LEFT JOIN lms.curriculum_sessions s ON s.id = p.source_session_id
    WHERE p.learner_id = auth.uid() AND p.module_id = target_module_id) END;
$$;

REVOKE ALL ON FUNCTION lms.list_session_teacher_candidates(uuid),
  lms.create_curriculum_session(uuid, text, timestamptz, timestamptz, uuid[]),
  lms.update_curriculum_session(uuid, text, timestamptz, timestamptz, uuid[]),
  lms.close_curriculum_session(uuid, text), lms.issue_session_qr_token(uuid),
  lms.revoke_session_qr_tokens(uuid), lms.add_session_attendees(uuid, uuid[]),
  lms.set_module_completion(uuid, uuid, boolean), lms.scan_session_qr(text),
  lms.get_my_module_completion(uuid)
  FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION lms.list_session_teacher_candidates(uuid),
  lms.create_curriculum_session(uuid, text, timestamptz, timestamptz, uuid[]),
  lms.update_curriculum_session(uuid, text, timestamptz, timestamptz, uuid[]),
  lms.close_curriculum_session(uuid, text), lms.issue_session_qr_token(uuid),
  lms.revoke_session_qr_tokens(uuid), lms.add_session_attendees(uuid, uuid[]),
  lms.set_module_completion(uuid, uuid, boolean), lms.scan_session_qr(text),
  lms.get_my_module_completion(uuid)
  TO authenticated;

-- ---------------------------------------------------------------------------
-- 9. Privileges and RLS. All session writes go through the RPCs above.
-- ---------------------------------------------------------------------------
REVOKE ALL ON lms.curriculum_sessions, lms.session_attendances,
  lms.session_teachers, lms.session_qr_tokens FROM anon, authenticated, service_role;
GRANT SELECT ON lms.curriculum_sessions, lms.session_attendances, lms.session_teachers TO authenticated;
-- Hashes are never selectable through the API; managers see metadata only.
GRANT SELECT (id, session_id, valid_from, expires_at, revoked_at, created_by, created_at)
  ON lms.session_qr_tokens TO authenticated;
-- Server-only reporting/fixture access (same pattern as Phase 1). No token access.
GRANT SELECT, INSERT, UPDATE, DELETE ON lms.curriculum_sessions, lms.session_attendances,
  lms.session_teachers TO service_role;

ALTER TABLE lms.session_teachers ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.session_qr_tokens ENABLE ROW LEVEL SECURITY;

CREATE POLICY "sessions: authorized viewers" ON lms.curriculum_sessions FOR SELECT TO authenticated
  USING (lms.can_view_session(id) AND (deleted_at IS NULL OR lms.is_super_admin()));
CREATE POLICY "session_teachers: authorized viewers" ON lms.session_teachers FOR SELECT TO authenticated
  USING (lms.can_view_session(session_id));
CREATE POLICY "session_qr_tokens: managers read metadata" ON lms.session_qr_tokens FOR SELECT TO authenticated
  USING (lms.is_session_manager(session_id));
CREATE POLICY "session_attendances: learner own or session staff" ON lms.session_attendances
  FOR SELECT TO authenticated
  USING ((learner_id = (SELECT auth.uid()) AND lms.is_active_app_user((SELECT auth.uid())))
    OR lms.is_session_manager(session_id) OR lms.is_session_teacher(session_id)
    OR lms.has_admin_permission('view_session_tracking'));

-- Session teachers can read the progress of learners who attended their sessions.
CREATE POLICY "progress: session teacher" ON lms.learner_progress FOR SELECT TO authenticated
  USING (lms.is_session_teacher_for_learner(learner_id, module_id));

-- Study notes: completion-gated; no broad authenticated read.
DROP POLICY IF EXISTS "storage: study notes read accessible current version" ON storage.objects;
CREATE POLICY "storage: study notes read authorized current version" ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'study-notes'
    AND lms.is_active_app_user(auth.uid())
    AND (lms.is_super_admin() OR EXISTS (
      SELECT 1 FROM lms.module_versions mv
      WHERE mv.storage_path = storage.objects.name AND mv.is_current
        AND lms.can_access_module_notes(mv.module_id)))
  );

COMMIT;
